import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a number theory contest, let {m} and {n} be odd, coprime integers with m, n >= 3. Fix residue classes {r_mod_m} modulo m and {s_mod_n} modulo n, and also distinct residue classes {r2_mod_m} modulo m and {s2_mod_n} modulo n. Determine the minimal integer t such that there exist a positive integer x that is the product of t distinct primes (with 2 among them) and gcd(x, m*n) = 1, and some interval of consecutive integers [a+1, a+b] that contains exactly {a_target} integers y satisfying y^2 ≡ 1 (mod x), y ≡ {r_mod_m} (mod m), y ≡ {s_mod_n} (mod n), and exactly {b_target} integers z satisfying z^2 ≡ 1 (mod x), z ≡ {r2_mod_m} (mod m), z ≡ {s2_mod_n} (mod n). Your final answer should be the minimal t.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Sample odd m, n >= 3 and coprime
def sample_odd(lo=3, hi=199):
    while True:
        x = rng.randint(lo, hi)
        if x % 2 == 1 and x >= 3:
            return x
for _ in range(1000):
    m = sample_odd()
    # sample n coprime to m
    tries = 0
    while True:
        n = sample_odd()
        if __import__('math').gcd(m, n) == 1:
            break
        tries += 1
        if tries > 200:
            m = sample_odd()
            tries = 0
    r_mod_m = rng.randint(0, m - 1)
    s_mod_n = rng.randint(0, n - 1)
    # ensure distinct secondary residues
    r2_choices = list(range(m))
    if r_mod_m in r2_choices:
        r2_choices.remove(r_mod_m)
    r2_mod_m = rng.choice(r2_choices)
    s2_choices = list(range(n))
    if s_mod_n in s2_choices:
        s2_choices.remove(s_mod_n)
    s2_mod_n = rng.choice(s2_choices)
    # choose targets; a_target big enough to ensure nontrivial minimal t
    a_target = rng.randint(2**10, 2**20)  # 1024..1,048,576
    b_target = rng.randint(50, 5000)
    # sanity check
    if m >= 3 and n >= 3 and m % 2 == 1 and n % 2 == 1 and __import__('math').gcd(m, n) == 1:
        return {
            'm': m,
            'n': n,
            'r_mod_m': r_mod_m,
            's_mod_n': s_mod_n,
            'r2_mod_m': r2_mod_m,
            's2_mod_n': s2_mod_n,
            'a_target': a_target,
            'b_target': b_target
        }
# Fallback (should rarely happen)
m, n = 3, 5
return {
    'm': m,
    'n': n,
    'r_mod_m': 1,
    's_mod_n': 2,
    'r2_mod_m': 0,
    's2_mod_n': 1,
    'a_target': 1024,
    'b_target': 100
}

    def verifier(assign):
# Validate domain constraints
import math
required = ['m','n','r_mod_m','s_mod_n','r2_mod_m','s2_mod_n','a_target','b_target']
for k in required:
    if k not in assign:
        # Missing slot
        return (False, None)
m = assign['m']; n = assign['n']
r_mod_m = assign['r_mod_m']; s_mod_n = assign['s_mod_n']
r2_mod_m = assign['r2_mod_m']; s2_mod_n = assign['s2_mod_n']
a_target = assign['a_target']; b_target = assign['b_target']
# Basic checks
if not (isinstance(m, int) and isinstance(n, int) and isinstance(r_mod_m, int) and isinstance(s_mod_n, int) and isinstance(r2_mod_m, int) and isinstance(s2_mod_n, int) and isinstance(a_target, int) and isinstance(b_target, int)):
    return (False, None)
if m < 3 or n < 3 or m % 2 == 0 or n % 2 == 0:
    return (False, None)
if math.gcd(m, n) != 1:
    return (False, None)
if not (0 <= r_mod_m < m and 0 <= r2_mod_m < m and 0 <= s_mod_n < n and 0 <= s2_mod_n < n):
    return (False, None)
if r_mod_m == r2_mod_m or s_mod_n == s2_mod_n:
    return (False, None)
if a_target <= 0 or b_target <= 0:
    return (False, None)
# Minimal t computation: with x the product of t distinct primes including 2,
# the number of solutions to y^2 ≡ 1 (mod x) per residue-lift block of length x
# equals 2^{t-1} (since modulo 2 only y ≡ 1 works, and each odd prime contributes ±1).
# To ensure an interval that can contain exactly a_target solutions of the first residue-pair,
# we need 2^{t-1} >= a_target. The minimal such t is ceil(log2(a_target)) + 1.
# Use bit_length to avoid floating error.
t_min = (a_target - 1).bit_length() + 1
# Return the numeric answer
return (True, t_min)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

